void LoadExternalDLL()
{
    OPENFILENAMEA ofn = {0};
    char szFile[MAX_PATH] = {0};

    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = GetDesktopWindow();
    ofn.lpstrFilter = "DLL Files\0*.dll\0All Files\0*.*\0";
    ofn.lpstrFile = szFile;
    ofn.nMaxFile = MAX_PATH;
    ofn.Flags = OFN_FILEMUSTEXIST | OFN_HIDEREADONLY | OFN_NOCHANGEDIR;
    ofn.lpstrTitle = "ÇëÑ¡ÔñÒª×¢ÈëµÄÍâ¹Ò DLL";

    if (GetOpenFileNameA(&ofn))
    {
        // ´ò¿ªDLLÎÄ¼þ
        HANDLE hFile = CreateFileA(szFile, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
        if (hFile == INVALID_HANDLE_VALUE)
        {
            MessageBoxA(NULL, "ÎÞ·¨´ò¿ªDLLÎÄ¼þ", "´íÎó", MB_OK);
            return;
        }
        DWORD fileSize = GetFileSize(hFile, NULL);
        BYTE* rawData = (BYTE*)malloc(fileSize);
        DWORD bytesRead;
        if (!ReadFile(hFile, rawData, fileSize, &bytesRead, NULL) || bytesRead != fileSize)
        {
            MessageBoxA(NULL, "¶ÁÈ¡DLLÎÄ¼þÊ§°Ü", "´íÎó", MB_OK);
            free(rawData);
            CloseHandle(hFile);
            return;
        }
        CloseHandle(hFile);

        // ÊÖ¶¯Ó³Éä¼ÓÔØ (´«µÝÊý¾ÝÖ¸ÕëºÍ´óÐ¡)
        HMEMORYMODULE hMod = MemoryLoadLibrary(rawData, fileSize);
        free(rawData);  // MemoryLoadLibrary ÄÚ²¿ÒÑ¸´ÖÆÊý¾Ý£¬¿ÉÒÔÊÍ·Å

        if (hMod)
            MessageBoxA(NULL, "Íâ¹Ò DLL ÊÖ¶¯Ó³Éä³É¹¦£¡", "×¢ÈëÆ÷", MB_OK | MB_ICONINFORMATION);
        else
            MessageBoxA(NULL, "ÊÖ¶¯Ó³ÉäÊ§°Ü", "×¢ÈëÆ÷", MB_OK | MB_ICONERROR);
    }
}




